const rDrawn = () => Math.min(0.40, Math.max(0.03, rPhys()));

function boundaryT(p, dir) {
  let t = Infinity;
  if (dir.x > 1e-9) t = Math.min(t, (10.35 - p.x) / dir.x);
  if (dir.x < -1e-9) t = Math.min(t, (-0.35 - p.x) / dir.x);
  if (dir.y > 1e-9) t = Math.min(t, (4.4 - p.y) / dir.y);
  if (dir.y < -1e-9) t = Math.min(t, (-4.4 - p.y) / dir.y);
  return Math.max(0.05, Math.min(t, 40));
}
// Rutherford: theta = 2*atan(dClose / (2b)), dClose = 2 * nucleus radius
function traceTraj(y0) {
  const r = rPhys(), dClose = 2 * r, infl = Math.max(6 * r, 0.09);
  let p = P(-0.45, y0), dir = P(1, 0);
  const pts = [p.clone()];
  let bMin = Infinity;
  for (let it = 0; it < 8; it++) {
    let best = null;
    for (const n of nuclei) {
      const wx = n.x - p.x, wy = n.y - p.y;
      const t = wx * dir.x + wy * dir.y;
      if (t < 1e-3) continue;
      const b = Math.abs(dir.x * wy - dir.y * wx);
      if (b < infl && (!best || t < best.t)) best = { t, b, n };
    }
    if (!best) break;
    const cp = p.clone().add(dir.clone().multiplyScalar(best.t));
    if (cp.x < -0.45 || cp.x > 10.35 || cp.y < -4.4 || cp.y > 4.4) break;
    pts.push(cp);
    const wx = best.n.x - cp.x, wy = best.n.y - cp.y;
    const cross = dir.x * wy - dir.y * wx;
    const b = Math.max(best.b, 1e-4);
    bMin = Math.min(bMin, b);
    const theta = 2 * Math.atan(dClose / (2 * b));
    dir.rotateAround(P(0, 0), (cross >= 0 ? -1 : 1) * theta);
    p = cp;
  }
  pts.push(p.clone().add(dir.clone().multiplyScalar(boundaryT(p, dir))));
  return { pts, bMin, deg: Math.abs(THREE.MathUtils.radToDeg(Math.atan2(dir.y, dir.x))) };
}

