<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ELEMENT SPEC (one line per drawn element)
   left frame           → Line rectangle, black
   gold foil            → ShapeGeometry leaning parallelogram #F5D33A + right edge strip #E08A1E + LineLoop #9A6B08
   incoming beam        → tapered quad mesh #7DD321 (0.5 → 0.08 thick)
   exit rays (6)        → ribbon quads + triangle heads #7DD321 at 0,±8,±16,+24°
   impact box           → 4 thin black plane bars (0.7 × 1.0 outline)
   'Gold foil' leader   → Line black
   grey block arrow     → ShapeGeometry #D9D9D9 + LineLoop #333
   right frame          → Line rectangle, black
   foil band            → PlaneGeometry(5.2,9) #FCF3B6 + two 0.08 strips #E9A020
   gold atoms (4×7)     → PlaneGeometry(1.34) + saturated radial-gradient CanvasTexture (baked shading + rim)
   nuclei (28)          → CircleGeometry #8B1A0A (min drawn r=0.055) + translucent cross-section halo
   static rays (8)      → ribbons + heads #7DD321 (4 undeflected, 2 slight, 2 backscattered)
   interactive ray      → rebuilt ribbon + head #2E7D0F with draggable handle circles
   beam particles (40)  → pooled comet ribbons #5FBF12
   callout leaders (4)  → Lines black
   all text             → addLabel HTML overlays
*/

const P = (x, y) => new THREE.Vector2(x, y);
const V3 = (x, y, z = 0) => new THREE.Vector3(x, y, z);
const GREEN = 0x7DD321, DGREEN = 0x2E7D0F;

const matGreen = new THREE.MeshBasicMaterial({ color: GREEN, side: THREE.DoubleSide });
const matDGreen = new THREE.MeshBasicMaterial({ color: DGREEN, side: THREE.DoubleSide });
const matBeam = new THREE.MeshBasicMaterial({ color: 0x5FBF12, side: THREE.DoubleSide });
const matInk = new THREE.MeshBasicMaterial({ color: 0x000000, side: THREE.DoubleSide });
const matRed = new THREE.MeshBasicMaterial({ color: 0x8B1A0A, side: THREE.DoubleSide });
const matHalo = new THREE.MeshBasicMaterial({ color: 0xC2321A, transparent: true, opacity: 0.18, side: THREE.DoubleSide });

/* ---------------- generic flat-geometry helpers ---------------- */
function ribbonGeom(pts, w, z = 0) {
  const h = w / 2, v = [];
  for (let i = 0; i < pts.length - 1; i++) {
    const a = pts[i], b = pts[i + 1];
    const dx = b.x - a.x, dy = b.y - a.y, L = Math.hypot(dx, dy);
    if (L < 1e-6) continue;
    const nx = -dy / L * h, ny = dx / L * h;
    v.push(a.x + nx, a.y + ny, z, a.x - nx, a.y - ny, z, b.x - nx, b.y - ny, z,
           a.x + nx, a.y + ny, z, b.x - nx, b.y - ny, z, b.x + nx, b.y + ny, z);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(v, 3));
  return g;
}
function headMesh(tip, ang, len, mat, z) {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(
    [0, 0, 0, -len, len * 0.58, 0, -len, -len * 0.58, 0], 3));
  const m = new THREE.Mesh(g, mat);
  m.position.set(tip.x, tip.y, z); m.rotation.z = ang;
  return m;
}
function rayGroup(pts, { w = 0.22, mat = matGreen, head = 0.45, z = 0.06 } = {}) {
  const g = new THREE.Group();
  g.add(new THREE.Mesh(ribbonGeom(pts, w, z), mat));
  for (let i = 1; i < pts.length - 1; i++) {
    const c = new THREE.Mesh(new THREE.CircleGeometry(w / 2, 14), mat);
    c.position.set(pts[i].x, pts[i].y, z); g.add(c);
  }
  if (head > 0 && pts.length >= 2) {
    const a = pts[pts.length - 2], b = pts[pts.length - 1];
    g.add(headMesh(b, Math.atan2(b.y - a.y, b.x - a.x), head, mat, z + 0.002));
  }
  return g;
}
function polyLine(pts, color, z, parent) {
  const l = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints(pts.map(p => V3(p.x, p.y, z))),
    new THREE.LineBasicMaterial({ color }));
  if (parent) parent.add(l);
  return l;
}
function rectLine(x0, y0, x1, y1, color, z, parent) {
  return polyLine([P(x0, y0), P(x1, y0), P(x1, y1), P(x0, y1), P(x0, y0)], color, z, parent);
}
function bar(cx, cy, w, h, mat, z, parent) {
  const m = new THREE.Mesh(new THREE.PlaneGeometry(w, h), mat);
  m.position.set(cx, cy, z);
  if (parent) parent.add(m);
  return m;
}
function taperQuad(a, b, wa, wb, mat, z, parent) {
  const dx = b.x - a.x, dy = b.y - a.y, L = Math.hypot(dx, dy);
  const nx = -dy / L, ny = dx / L, v = [];
  v.push(a.x + nx * wa / 2, a.y + ny * wa / 2, z, a.x - nx * wa / 2, a.y - ny * wa / 2, z,
         b.x - nx * wb / 2, b.y - ny * wb / 2, z,
         a.x + nx * wa / 2, a.y + ny * wa / 2, z, b.x - nx * wb / 2, b.y - ny * wb / 2, z,
         b.x + nx * wb / 2, b.y + ny * wb / 2, z);
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(v, 3));
  const m = new THREE.Mesh(g, mat);
  if (parent) parent.add(m);
  return m;
}
function disposeTree(o) { o.traverse?.(n => { n.geometry?.dispose?.(); }); }

/* ================= LEFT PANEL : macroscopic view ================= */
const leftGroup = new THREE.Group(); scene.add(leftGroup);
rectLine(-11, -4.5, -2.5, 4.0, 0x000000, 0.0, leftGroup);

// gold foil: leaning parallelogram (flat 2D diagram, front-on camera)
const FC = -6.8, FH = 3.2, FW = 1.4, FSH = 0.5;
const fBL = P(FC + FSH / 2 - FW / 2, -FH);
const fBR = P(FC + FSH / 2 + FW / 2, -FH);
const fTR = P(FC - FSH / 2 + FW / 2, FH);
const fTL = P(FC - FSH / 2 - FW / 2, FH);
const foilShape = new THREE.Shape([fBL, fBR, fTR, fTL]);
const foil = new THREE.Mesh(new THREE.ShapeGeometry(foilShape),
  new THREE.MeshBasicMaterial({ color: 0xF5D33A, side: THREE.DoubleSide }));
foil.position.z = 0.0; leftGroup.add(foil);
// darker right edge strip (the plate's thickness catching light)
const EW = 0.17;
const edgeShape = new THREE.Shape([
  P(fBR.x - EW, fBR.y), P(fBR.x, fBR.y), P(fTR.x, fTR.y), P(fTR.x - EW, fTR.y)]);
const foilEdgeStrip = new THREE.Mesh(new THREE.ShapeGeometry(edgeShape),
  new THREE.MeshBasicMaterial({ color: 0xE08A1E, side: THREE.DoubleSide }));
foilEdgeStrip.position.z = 0.01; leftGroup.add(foilEdgeStrip);
leftGroup.add(new THREE.LineLoop(
  new THREE.BufferGeometry().setFromPoints([fBL, fBR, fTR, fTL].map(p => V3(p.x, p.y, 0.02))),
  new THREE.LineBasicMaterial({ color: 0x9A6B08 })));
polyLine([P(fBR.x - EW, fBR.y), P(fTR.x - EW, fTR.y)], 0xB8860B, 0.02, leftGroup);

// incoming beam (thick band narrowing to the impact point)
const impact = P(-6.72, 0);
taperQuad(P(-10.9, 0), P(-6.95, 0), 0.5, 0.09, matGreen, 0.06, leftGroup);

// fan of exit rays
function clipRay(o, angDeg, xMax, yMin, yMax) {
  const a = THREE.MathUtils.degToRad(angDeg);
  const dx = Math.cos(a), dy = Math.sin(a);
  let t = (xMax - o.x) / dx;
  if (dy > 0) t = Math.min(t, (yMax - o.y) / dy);
  else if (dy < 0) t = Math.min(t, (yMin - o.y) / dy);
  return P(o.x + dx * t, o.y + dy * t);
}
[0, 8, -8, 16, -16, 24].forEach(a => {
  leftGroup.add(rayGroup([impact, clipRay(impact, a, -2.75, -3.9, 3.5)],
    { w: 0.22, head: 0.42, z: 0.06 }));
});

// magnified-region box on the foil (4 thin bars, always in front)
(function box(cx, cy, w, h, t) {
  bar(cx, cy + h / 2, w + t, t, matInk, 0.22, leftGroup);
  bar(cx, cy - h / 2, w + t, t, matInk, 0.22, leftGroup);
  bar(cx - w / 2, cy, t, h + t, matInk, 0.22, leftGroup);
  bar(cx + w / 2, cy, t, h + t, matInk, 0.22, leftGroup);
})(-6.72, 0, 0.7, 1.0, 0.07);

// 'Gold foil' leader
polyLine([P(-7.60, -3.75), P(-6.90, -3.05)], 0x000000, 0.02, leftGroup);

// grey magnification block arrow
(function blockArrow(a, b, w, headLen, headW) {
  const dir = b.clone().sub(a), L = dir.length(), ang = Math.atan2(dir.y, dir.x);
  const pts = [P(0, -w / 2), P(L - headLen, -w / 2), P(L - headLen, -headW / 2), P(L, 0),
               P(L - headLen, headW / 2), P(L - headLen, w / 2), P(0, w / 2)];
  const grp = new THREE.Group();
  grp.add(new THREE.Mesh(new THREE.ShapeGeometry(new THREE.Shape(pts)),
    new THREE.MeshBasicMaterial({ color: 0xD9D9D9, side: THREE.DoubleSide })));
  grp.add(new THREE.LineLoop(
    new THREE.BufferGeometry().setFromPoints(pts.map(p => V3(p.x, p.y, 0.01))),
    new THREE.LineBasicMaterial({ color: 0x333333 })));
  grp.position.set(a.x, a.y, -0.02); grp.rotation.z = ang;
  scene.add(grp);
})(P(-5.4, -4.35), P(-0.85, -2.75), 0.75, 1.0, 1.7);

/* ============ RIGHT PANEL : enlarged cross-section ============ */
const rightGroup = new THREE.Group(); scene.add(rightGroup);
rectLine(-0.5, -4.5, 10.5, 4.5, 0x000000, 0.0, rightGroup);

// pale foil band + orange borders
const band = new THREE.Mesh(new THREE.PlaneGeometry(5.2, 9),
  new THREE.MeshBasicMaterial({ color: 0xFCF3B6, side: THREE.DoubleSide }));
band.position.set(5.2, 0, -0.06); rightGroup.add(band);
[2.6, 7.8].forEach(x => {
  const s = new THREE.Mesh(new THREE.PlaneGeometry(0.08, 9),
    new THREE.MeshBasicMaterial({ color: 0xE9A020, side: THREE.DoubleSide }));
  s.position.set(x, 0, -0.04); rightGroup.add(s);
});

// baked radial-gradient gold-ball texture (saturated, full-bleed, dark rim)
function atomTexture() {
  const s = 512, cv = document.createElement('canvas'); cv.width = cv.height = s;
  const g = cv.getContext('2d');
  const R = s / 2;
  const grd = g.createRadialGradient(s * 0.35, s * 0.30, s * 0.015, s * 0.50, s * 0.50, R);
  grd.addColorStop(0.00, '#FDF3AE');
  grd.addColorStop(0.16, '#F3DC5E');
  grd.addColorStop(0.42, '#E2BA2A');
  grd.addColorStop(0.70, '#CC9A18');
  grd.addColorStop(0.90, '#B07C10');
  grd.addColorStop(1.00, '#946409');
  g.beginPath(); g.arc(R, R, R, 0, Math.PI * 2);
  g.fillStyle = grd; g.fill();
  g.beginPath(); g.arc(R, R, R - 2.5, 0, Math.PI * 2);
  g.lineWidth = 5; g.strokeStyle = '#7A5209'; g.stroke();
  const tex = new THREE.CanvasTexture(cv);
  tex.anisotropy = renderer.capabilities.getMaxAnisotropy?.() || 1;
  tex.minFilter = THREE.LinearFilter;
  return tex;
}
const atomMat = new THREE.MeshBasicMaterial({ map: atomTexture(), transparent: true, side: THREE.DoubleSide });
const atomGeo = new THREE.PlaneGeometry(1.34, 1.34);   // slight overlap → no gaps between balls
const circGeo = new THREE.CircleGeometry(1, 28);

const COLS = [3.25, 4.55, 5.85, 7.15];
const ROWS = [3.9, 2.6, 1.3, 0.0, -1.3, -2.6, -3.9];
const nuclei = [];
const atomMeshes = [];
for (const x of COLS) for (const y of ROWS) {
  const a = new THREE.Mesh(atomGeo, atomMat);
  a.position.set(x, y, 0); rightGroup.add(a); atomMeshes.push(a);
  const halo = new THREE.Mesh(circGeo, matHalo);
  halo.position.set(x, y, 0.02); halo.visible = false; rightGroup.add(halo);
  const dot = new THREE.Mesh(circGeo, matRed);
  dot.position.set(x, y, 0.04); rightGroup.add(dot);
  nuclei.push({ x, y, dot, halo });
}

// static rays from the printed figure
const RX = 10.3, tan13 = Math.tan(THREE.MathUtils.degToRad(13));
[2.6, 0.6, -0.6, -2.0].forEach(y =>
  rightGroup.add(rayGroup([P(-0.45, y), P(RX, y)], { w: 0.22, head: 0.45, z: 0.06 })));
rightGroup.add(rayGroup([P(-0.45, 1.9), P(3.9, 1.9), P(RX, 1.9 + 6.4 * tan13)], { z: 0.06 }));
rightGroup.add(rayGroup([P(-0.45, -1.6), P(3.9, -1.6), P(RX, -1.6 + 6.4 * tan13)], { z: 0.06 }));
rightGroup.add(rayGroup([P(-0.45, 1.32), P(4.2, 1.32), P(-0.3, 3.95)], { z: 0.06 }));
rightGroup.add(rayGroup([P(-0.45, -1.05), P(4.0, -1.05), P(-0.3, -4.05)], { z: 0.06 }));

// callout leader lines
polyLine([P(0.8, 6.20), P(2.20, 2.72)], 0x000000, 0.02, rightGroup);
polyLine([P(3.3, 6.50), P(1.15, 3.10)], 0x000000, 0.02, rightGroup);
polyLine([P(6.6, 6.45), P(4.60, 2.05)], 0x000000, 0.02, rightGroup);
polyLine([P(9.6, 6.40), P(7.18, 3.95)], 0x000000, 0.02, rightGroup);

/* ---------- interactive trajectory + drag handle ---------- */
const trajGroup = new THREE.Group(); rightGroup.add(trajGroup);
const handleGroup = new THREE.Group(); rightGroup.add(handleGroup);
const hOuter = new THREE.Mesh(circGeo, new THREE.MeshBasicMaterial({ color: 0x1B5E20, side: THREE.DoubleSide }));
hOuter.scale.setScalar(0.24); handleGroup.add(hOuter);
const hInner = new THREE.Mesh(circGeo, new THREE.MeshBasicMaterial({ color: 0xB9F26A, side: THREE.DoubleSide }));
hInner.scale.setScalar(0.13); hInner.position.z = 0.01; handleGroup.add(hInner);

const R_TRUE = 0.018;
const R_MIN_DRAW = 0.055;         // keeps the nucleus dot legible at 1×
let nucMult = 1;
let dragY = 0.65, dragTarget = 0.65;
const rPhys = () => R_TRUE * nucMult;
const rDrawn = () => Math.min(0.40, Math.max(R_MIN_DRAW, rPhys()));

function boundaryT(p, dir) {
  let t = Infinity;
  if (dir.x > 1e-9) t = Math.min(t, (10.35 - p.x) / dir.x);
  if (dir.x < -1e-9) t = Math.min(t, (-0.35 - p.x) / dir.x);
  if (dir.y > 1e-9) t = Math.min(t, (4.4 - p.y) / dir.y);
  if (dir.y < -1e-9) t = Math.min(t, (-4.4 - p.y) / dir.y);
  return Math.max(0.05, Math.min(t, 40));
}
// Rutherford: theta = 2*atan(dClose / (2b)), dClose = 2 * nucleus radius
function traceTraj(y0) {
  const r = rPhys(), dClose = 2 * r, infl = Math.max(6 * r, 0.09);
  let p = P(-0.45, y0), dir = P(1, 0);
  const pts = [p.clone()];
  let bMin = Infinity;
  for (let it = 0; it < 8; it++) {
    let best = null;
    for (const n of nuclei) {
      const wx = n.x - p.x, wy = n.y - p.y;
      const t = wx * dir.x + wy * dir.y;
      if (t < 1e-3) continue;
      const b = Math.abs(dir.x * wy - dir.y * wx);
      if (b < infl && (!best || t < best.t)) best = { t, b, n };
    }
    if (!best) break;
    const cp = p.clone().add(dir.clone().multiplyScalar(best.t));
    if (cp.x < -0.45 || cp.x > 10.35 || cp.y < -4.4 || cp.y > 4.4) break;
    pts.push(cp);
    const wx = best.n.x - cp.x, wy = best.n.y - cp.y;
    const cross = dir.x * wy - dir.y * wx;
    const b = Math.max(best.b, 1e-4);
    bMin = Math.min(bMin, b);
    const theta = 2 * Math.atan(dClose / (2 * b));
    dir.rotateAround(P(0, 0), (cross >= 0 ? -1 : 1) * theta);
    p = cp;
  }
  pts.push(p.clone().add(dir.clone().multiplyScalar(boundaryT(p, dir))));
  return { pts, bMin, deg: Math.abs(THREE.MathUtils.radToDeg(Math.atan2(dir.y, dir.x))) };
}

let dragLabel = null;
function rebuildTraj() {
  while (trajGroup.children.length) {
    const c = trajGroup.children.pop(); trajGroup.remove(c); disposeTree(c);
  }
  const tr = traceTraj(dragY);
  trajGroup.add(rayGroup(tr.pts, { w: 0.24, mat: matDGreen, head: 0.52, z: 0.10 }));
  handleGroup.position.set(-0.45, dragY, 0.12);
  if (dragLabel) dragLabel.pos.set(-0.45, dragY, 0.12);
  const out = document.getElementById('dragOut');
  if (out) {
    const b = tr.bMin === Infinity ? null : tr.bMin;
    out.innerHTML = b === null
      ? '<i>b</i> &gt; influence range &rarr; &theta; &asymp; 0&deg; (straight through)'
      : `<i>b</i> = ${b.toFixed(3)} (${(b / rPhys()).toFixed(1)} &times; r<sub>nuc</sub>) &rarr; &theta; = ${tr.deg.toFixed(1)}&deg;`;
  }
}
function updateNucleus() {
  const rd = rDrawn(), rp = rPhys();
  for (const n of nuclei) {
    n.dot.scale.setScalar(rd);
    n.halo.scale.setScalar(rp);
    n.halo.visible = rp > rd * 1.05;
  }
  const o = document.getElementById('nucOut'); if (o) o.textContent = nucMult + '\u00D7';
  const nt = document.getElementById('nucNote');
  if (nt) nt.innerHTML = `scattering radius = ${rp.toFixed(3)} world units (atom radius 0.65) &middot; cross-section &prop; r<sup>2</sup> = ${(nucMult * nucMult).toLocaleString()}&times; the real value`;
  rebuildTraj();
}

/* ---------- pooled fire-beam animation ---------- */
const beamGroup = new THREE.Group(); rightGroup.add(beamGroup);
const pool = [];
for (let i = 0; i < 40; i++) {
  const m = new THREE.Mesh(new THREE.BufferGeometry(), matBeam);
  m.visible = false; beamGroup.add(m);
  pool.push({ mesh: m, active: false, s: 0, pts: null, cum: null, len: 0, deg: 0, delay: Math.random() * 2.5 });
}
let beamOn = false;
const stats = { fired: 0, slight: 0, strong: 0 };
function spawn(p) {
  const tr = traceTraj(THREE.MathUtils.randFloat(-4.2, 4.2));
  p.pts = tr.pts; p.deg = tr.deg;
  p.cum = [0];
  for (let i = 1; i < p.pts.length; i++) p.cum.push(p.cum[i - 1] + p.pts[i].distanceTo(p.pts[i - 1]));
  p.len = p.cum[p.cum.length - 1];
  p.s = 0; p.active = true;
}
function pointAt(p, s) {
  s = Math.max(0, Math.min(s, p.len));
  for (let i = 1; i < p.cum.length; i++) {
    if (s <= p.cum[i]) {
      const f = (s - p.cum[i - 1]) / Math.max(1e-6, p.cum[i] - p.cum[i - 1]);
      return p.pts[i - 1].clone().lerp(p.pts[i], f);
    }
  }
  return p.pts[p.pts.length - 1].clone();
}
function subPath(p, s0, s1) {
  const out = [pointAt(p, s0)];
  for (let i = 0; i < p.cum.length; i++) if (p.cum[i] > s0 && p.cum[i] < s1) out.push(p.pts[i]);
  out.push(pointAt(p, s1));
  return out;
}
let statTimer = 0;
function updateBeam(dt) {
  if (!beamOn) {
    for (const p of pool) { p.mesh.visible = false; p.active = false; }
    return;
  }
  for (const p of pool) {
    if (!p.active) {
      p.delay -= dt;
      if (p.delay <= 0) spawn(p); else { p.mesh.visible = false; continue; }
    }
    p.s += 7 * dt;
    if (p.s >= p.len) {
      stats.fired++;
      if (p.deg > 45) stats.strong++; else if (p.deg > 5) stats.slight++;
      p.active = false; p.mesh.visible = false; p.delay = Math.random() * 0.7;
      continue;
    }
    const seg = subPath(p, Math.max(0, p.s - 1.1), p.s);
    const old = p.mesh.geometry;
    p.mesh.geometry = ribbonGeom(seg, 0.11, 0.08);
    old?.dispose?.();
    p.mesh.visible = true;
  }
  statTimer += dt;
  if (statTimer > 0.2) {
    statTimer = 0;
    const el = document.getElementById('beamOut');
    if (el) el.textContent = `fired ${stats.fired} · slightly deflected ${stats.slight} · strongly deflected ${stats.strong}`;
  }
}

/* ================= CAMERA FRAMING ================= */
const VIEWS = {
  both:  { x0: -11.6, x1: 11.2, y0: -6.3, y1: 8.1 },
  macro: { x0: -11.4, x1: -2.0, y0: -5.1, y1: 4.4 },
  micro: { x0: -1.1, x1: 11.1, y0: -6.2, y1: 8.1 }
};
let viewMode = 'both';
let camMoved = false;
controls.addEventListener('start', () => { camMoved = true; });
function frameView() {
  const v = VIEWS[viewMode];
  const cx = (v.x0 + v.x1) / 2, cy = (v.y0 + v.y1) / 2;
  const halfW = (v.x1 - v.x0) / 2, halfH = (v.y1 - v.y0) / 2;
  const asp = Math.max(0.2, canvas.clientWidth / Math.max(1, canvas.clientHeight));
  const z = Math.min(3 / halfH, 3 * asp / halfW) * 0.98;
  setCameraView({ projection: 'orthographic', axisScreenAngles: null, rollDeg: 0, heightFraction: 0.7, zoom: z, target: [cx, cy, 0] });
  camMoved = false;
}
frameView();
