// pointer dragging of the trajectory
const myRay = new THREE.Raycaster();
const zPlane = new THREE.Plane(new THREE.Vector3(0, 0, 1), 0);
const hitPt = new THREE.Vector3();
let dragging = false;
function worldFromEvent(ev) {
  const r = canvas.getBoundingClientRect();
  const nd = new THREE.Vector2(((ev.clientX - r.left) / r.width) * 2 - 1,
                               -((ev.clientY - r.top) / r.height) * 2 + 1);
  myRay.setFromCamera(nd, camera);
  return myRay.ray.intersectPlane(zPlane, hitPt) ? hitPt.clone() : null;
}
canvas.addEventListener('pointerdown', ev => {
  const w = worldFromEvent(ev);
  if (!w) return;
  if (Math.hypot(w.x + 0.45, w.y - dragY) < 0.7) {
    dragging = true; controls.enabled = false; canvas.style.cursor = 'grabbing';
  }
});
window.addEventListener('pointermove', ev => {
  if (!dragging) return;
  const w = worldFromEvent(ev);
  if (!w) return;
  dragY = dragTarget = THREE.MathUtils.clamp(w.y, -4.25, 4.25);
  rebuildTraj();
});
window.addEventListener('pointerup', () => {
  if (dragging) { dragging = false; controls.enabled = true; canvas.style.cursor = 'default'; }
});

