// own animation loop (tween + beam)
let _t0 = performance.now();
(function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  const dt = Math.min(0.05, (now - _t0) / 1000); _t0 = now;
  if (!dragging && Math.abs(dragY - dragTarget) > 1e-4) {
    dragY += (dragTarget - dragY) * Math.min(1, dt * 7);
    if (Math.abs(dragY - dragTarget) < 1e-4) dragY = dragTarget;
    rebuildTraj();
  }
  updateBeam(dt);
})();
